  openModal(
    `<div class="modal-head">
      <div>
        <h2>${esc(info.label || "Documento")}${inv.number ? ` ${esc(inv.number)}` : ""}</h2>
        <p>${esc(sup.name || "Sin proveedor")} · ${fmtEUR(inv.total)}</p>
